"use strict";(globalThis.webpackChunkmy_website||=[]).push([[7847],{20894(e){e.exports=JSON.parse('{"slug":"hydra-head","title":"Hydra Head","short":"An off-chain micro-ledger between a small group of participants in the Hydra Layer 2 protocol.","category":"network","aliases":["Head"],"mentalModel":null,"related":["hydra","layer-2"],"sources":[],"link":null,"level":"intermediate","body":"An off-chain ledger created by a small group of participants in the Hydra protocol. Inside a Head, participants exchange transactions at near-zero cost and very low latency without writing each one back to the main chain.\\n\\nWhen the Head closes, its final state is settled back to the Cardano mainnet. The chain only records the entry and exit of the Head, not every transaction within it."}')}}]);